// Renders nothing unless the question actually has an image (a diagram, graph,
// or figure some SAT/AP questions attach) — sized to the image's real aspect
// ratio so figures never get stretched or cropped.
const QuestionImage = ({ uri, style }) => {
  const [ratio, setRatio] = useState(16 / 10);
  useEffect(() => {
    if (!uri) return;
    Image.getSize(uri, (w, h) => { if (w && h) setRatio(w / h); }, () => {});
  }, [uri]);
  if (!uri) return null;
  return (
    <View style={[{ marginBottom: 16, borderRadius: 12, overflow: "hidden", backgroundColor: "#f1f5f9", alignItems: "center" }, style]}>
      <Image source={{ uri }} style={{ width: "100%", aspectRatio: ratio, maxHeight: 320 }} resizeMode="contain" />
    </View>
  );
};

