const AuthRipple = ({ isLight, mainCircleSize = 100 }) => {
  const anims = useRef([0, 1, 2].map(() => new Animated.Value(0))).current;

  useEffect(() => {
    const loops = anims.map((anim, i) =>
      Animated.loop(
        Animated.sequence([
          Animated.delay(i * 1100),
          Animated.timing(anim, {
            toValue: 1,
            duration: 3800,
            easing: Easing.out(Easing.quad),
            useNativeDriver: true,
          }),
          Animated.timing(anim, { toValue: 0, duration: 0, useNativeDriver: true }),
        ])
      )
    );
    loops.forEach((l) => l.start());
    return () => loops.forEach((l) => l.stop());
  }, [anims]);

  const ringBorder = isLight ? "rgba(37, 99, 235, 0.35)" : "rgba(79, 124, 255, 0.45)";
  const ringBg = isLight ? "rgba(37, 99, 235, 0.08)" : "rgba(79, 124, 255, 0.12)";

  return (
    <View style={{ position: "absolute", width: mainCircleSize * 4, height: mainCircleSize * 4, alignItems: "center", justifyContent: "center" }}>
      <View
        style={{
          width: mainCircleSize,
          height: mainCircleSize,
          borderRadius: mainCircleSize / 2,
          borderWidth: 1,
          borderColor: ringBorder,
          backgroundColor: ringBg,
        }}
      />
      {anims.map((anim, i) => {
        const scale = anim.interpolate({ inputRange: [0, 1], outputRange: [1, 3.2] });
        const opacity = anim.interpolate({ inputRange: [0, 0.15, 1], outputRange: [0.55, 0.35, 0] });
        return (
          <Animated.View
            key={i}
            style={{
              position: "absolute",
              width: mainCircleSize,
              height: mainCircleSize,
              borderRadius: mainCircleSize / 2,
              borderWidth: 1,
              borderColor: ringBorder,
              opacity,
              transform: [{ scale }],
            }}
          />
        );
      })}
    </View>
  );
};

const AuthOrbitDisplay = ({ isLight }) => {
  const spin = useRef(new Animated.Value(0)).current;
  const orbitR = 118;
  const hub = 140;

  useEffect(() => {
    const loop = Animated.loop(
      Animated.timing(spin, { toValue: 1, duration: 26000, easing: Easing.linear, useNativeDriver: true })
    );
    loop.start();
    return () => loop.stop();
  }, [spin]);

  const rotate = spin.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "360deg"] });
  const counterRotate = spin.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "-360deg"] });

  return (
    <View style={{ width: hub * 2, height: hub * 2, alignItems: "center", justifyContent: "center" }}>
      <Animated.View style={{ width: hub * 2, height: hub * 2, position: "absolute", transform: [{ rotate }] }}>
        {AUTH_ORBIT_ICONS.map((icon, i) => {
          const angle = (i / AUTH_ORBIT_ICONS.length) * Math.PI * 2 - Math.PI / 2;
          const x = orbitR * Math.cos(angle);
          const y = orbitR * Math.sin(angle);
          return (
            <Animated.View
              key={icon.name}
              style={{
                position: "absolute",
                left: hub + x - 22,
                top: hub + y - 22,
                width: 44,
                height: 44,
                borderRadius: 22,
                backgroundColor: isLight ? "#ffffff" : "#151c36",
                borderWidth: 1,
                borderColor: isLight ? "#dbeafe" : "#2a3a5c",
                alignItems: "center",
                justifyContent: "center",
                transform: [{ rotate: counterRotate }],
                ...(Platform.OS === "web" ? { boxShadow: "0 6px 18px rgba(15, 23, 42, 0.18)" } : {}),
              }}
            >
              <AppIcon name={icon.name} size={18} color={icon.color} />
            </Animated.View>
          );
        })}
      </Animated.View>
      <View
        style={{
          width: 64,
          height: 64,
          borderRadius: 16,
          backgroundColor: isLight ? "#ffffff" : "#1a2540",
          borderWidth: 1,
          borderColor: isLight ? "#dbeafe" : "#2a3a5c",
          alignItems: "center",
          justifyContent: "center",
          ...(Platform.OS === "web" ? { boxShadow: "0 8px 24px rgba(15, 23, 42, 0.2)" } : {}),
        }}
      >
        <Image source={require("./logo.png")} style={{ width: 44, height: 44, borderRadius: 10 }} resizeMode="contain" />
      </View>
    </View>
  );
};

