// Reduced-motion-aware count-up: animates 0 → value over motion.duration.slow
// using motion.easeOut; snaps instantly if the OS/browser prefers reduced motion.
const useCountUp = (value, { duration = motion.duration.slow } = {}) => {
  const [display, setDisplay] = useState(value);
  useEffect(() => {
    let cancelled = false;
    const run = (reduceMotion) => {
      if (reduceMotion || value == null) { setDisplay(value); return; }
      const anim = new Animated.Value(0);
      const start = display || 0;
      const id = anim.addListener(({ value: t }) => {
        if (!cancelled) setDisplay(Math.round(start + (value - start) * t));
      });
      Animated.timing(anim, { toValue: 1, duration, easing: motion.easeOut, useNativeDriver: false }).start();
      return () => anim.removeListener(id);
    };
    if (Platform.OS === "web") {
      run(typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches);
    } else {
      AccessibilityInfo.isReduceMotionEnabled().then((r) => { if (!cancelled) run(r); });
    }
    return () => { cancelled = true; };
  }, [value]);
  return display;
};

