/* ---------------- CONSTANTS ---------------- */
const ADMIN_EMAIL = "admin@ascendsat.com";

// Blocks obvious profanity/slurs from user-chosen display names. Deliberately
// conservative: word-boundary matching only, so it censors the word itself
// but never a legitimate name that happens to contain one as a substring
// (the classic "Scunthorpe problem"). Leetspeak substitutions (@, 4, 1, 3,
// 0 for a/i/e/o) are normalized before matching so simple evasions still get
// caught. False negatives on creative evasion are an acceptable tradeoff for
// never mangling a real name.
const PROFANITY_TERMS = [
  "fuck", "shit", "bitch", "asshole", "bastard", "cunt", "dick", "pussy",
  "cock", "whore", "slut", "faggot", "fag", "retard", "nigger", "nigga",
  "chink", "spic", "kike", "gook", "tranny", "rape", "rapist", "molest",
  "pedo", "pedophile", "nazi", "hitler", "kys", "suicide",
];
const censorName = (name) => {
  if (!name) return name;
  const normalize = (s) => s.replace(/[@4]/g, "a").replace(/3/g, "e").replace(/1/g, "i").replace(/0/g, "o").replace(/5/g, "s").replace(/7/g, "t");
  let result = name;
  PROFANITY_TERMS.forEach((term) => {
    // Match against a normalized copy but replace in the original string —
    // walk the original name, normalizing each candidate word before compare.
    const words = result.split(/(\s+)/);
    result = words.map((w) => {
      if (/^\s+$/.test(w) || w === "") return w;
      const bare = w.replace(/[^a-zA-Z0-9@$]/g, "");
      if (normalize(bare.toLowerCase()) === term) {
        const stars = "*".repeat(Math.max(bare.length - 1, 1));
        return w.replace(bare, bare[0] + stars);
      }
      return w;
    }).join("");
  });
  return result;
};

