  "https://script.google.com/macros/s/AKfycbx3Aye2OVFWLGQD1AglD1zi2olROhS5hoMlp5lT62RC9Ets7nT_0mbaSs0A_7z1QCKD/exec";

const MATH = [
  "Algebra",
  "Advanced Math",
  "Problem Solving and Data Analysis",
  "Geometry & Trigonometry",
];

const READING_WRITING = [
  "Information and Ideas",
  "Craft & Structure",
  "Expression of Ideas",
  "Standard English Conventions",
];

const getQuestionSubjectLabel = (domain) => {
  // Preserve legacy SAT labels exactly (RW domains -> "English"); other tests
  // use their section label (English / Math / Reading / Science).
  if (MATH.includes(domain)) return "Math";
  if (READING_WRITING.includes(domain)) return "English";
  return sectionLabelForDomain(domain);
};

const getQuestionOutcomeLabel = (userAns, correctAns) => {
  if (userAns === undefined || userAns === -1) return "Omitted";
  if (userAns === correctAns) return "Correct";
  return "Incorrect";
};

const normalizeDifficultyLabel = (difficulty) => {
  const value = String(difficulty || "Medium").trim();
  if (/^easy$/i.test(value)) return "Easy";
  if (/^hard$/i.test(value)) return "Hard";
  return "Medium";
};

const DOMAIN_TO_DIAG_KEY = {
  Algebra: "algebra",
  "Advanced Math": "advancedMath",
  "Problem Solving and Data Analysis": "dataAnalysis",
  "Geometry & Trigonometry": "geometry",
  "Information and Ideas": "infoIdeas",
  "Craft & Structure": "craftStructure",
  "Expression of Ideas": "expressionIdeas",
  "Standard English Conventions": "englishConventions",
};

/** Never project below the composite score the user gave during onboarding. */
const applyOnboardingScoreFloorToSections = (sectionScores, cfg, onboardingTotal) => {
  const floor = Number(onboardingTotal || 0);
  if (!floor) return { sectionScores, floored: false };

  const compositeSections = cfg.sections.filter((s) => s.inComposite);
  const values = compositeSections.map((s) => Number(sectionScores[s.label] || 0));
  const total = cfg.compositeFromSections(values);
  if (total >= floor) return { sectionScores, floored: false };

  if (cfg.id === "sat") {
    let math = Math.max(200, Number(sectionScores["Math"] || 200));
    let rw = Math.max(200, Number(sectionScores["Reading & Writing"] || 200));
    const curTotal = math + rw;
    if (curTotal < floor) {
      if (curTotal <= 0) {
        math = Math.round(floor / 2 / 10) * 10;
        rw = Math.max(200, floor - math);
      } else {
        math = Math.min(800, Math.round((math * (floor / curTotal)) / 10) * 10);
        rw = Math.max(200, floor - math);
        if (math + rw < floor) math = Math.min(800, Math.max(200, floor - rw));
      }
    }
    return {
      sectionScores: { ...sectionScores, Math: math, "Reading & Writing": rw },
      floored: true,
    };
  }

  const { sectionMin, sectionMax, compositeMin } = cfg.scale;
  if (total <= 0) {
    const per = Math.min(sectionMax, Math.max(sectionMin, Math.round(floor)));
    const out = { ...sectionScores };
    compositeSections.forEach((s) => { out[s.label] = per; });
    return { sectionScores: out, floored: true };
  }
  const ratio = floor / total;
  const out = { ...sectionScores };
  compositeSections.forEach((s) => {
    out[s.label] = Math.min(
      sectionMax,
      Math.max(sectionMin, Math.round(Number(sectionScores[s.label] || compositeMin) * ratio))
    );
  });
  let newTotal = cfg.compositeFromSections(compositeSections.map((s) => out[s.label]));
  if (newTotal < floor && compositeSections.length) {
    out[compositeSections[0].label] = Math.min(sectionMax, out[compositeSections[0].label] + (floor - newTotal));
  }
  return { sectionScores: out, floored: true };
};

const deriveDiagnosticFromExam = (questions, answers, cfg = getTestConfig("sat"), onboardingTotal = null) => {
  const bars = { ...cfg.defaultBars };
  const domainStats = {};

  questions.forEach((q, i) => {
    const key = cfg.domainToBarKey[q.domain];
    if (!key) return;
    if (!domainStats[key]) domainStats[key] = { correct: 0, total: 0 };
    domainStats[key].total += 1;
    if (answers[i] === q.answer) domainStats[key].correct += 1;
  });

  Object.entries(domainStats).forEach(([key, { correct, total }]) => {
    const acc = total > 0 ? correct / total : 0.5;
    bars[key] = Math.max(1, Math.min(7, Math.round(acc * 7) || 1));
  });

  // Correct/total per composite section.
  const compositeSections = cfg.sections.filter((s) => s.inComposite);
  const secStats = {};
  compositeSections.forEach((s) => { secStats[s.label] = { correct: 0, total: 0 }; });
  questions.forEach((q, i) => {
    const sec = cfg.sections.find((s) => s.domains.includes(q.domain));
    if (!sec || !sec.inComposite) return;
    secStats[sec.label].total += 1;
    if (answers[i] === q.answer) secStats[sec.label].correct += 1;
  });
  const totalCorrect = questions.reduce((sum, q, i) => sum + (answers[i] === q.answer ? 1 : 0), 0);

  if (cfg.id === "sat" || cfg.id === "act") {
    let irtResult = scoreDiagnosticWithIrt(questions, answers, cfg);

    if (cfg.id === "sat") {
      const m = secStats["Math"] || { correct: 0, total: 0 };
      const rw = secStats["Reading & Writing"] || { correct: 0, total: 0 };
      let sectionScores = {
        Math: irtResult.sectionScores["Math"] ?? 500,
        "Reading & Writing": irtResult.sectionScores["Reading & Writing"] ?? 500,
      };
      const { sectionScores: flooredScores, floored } = applyOnboardingScoreFloorToSections(sectionScores, cfg, onboardingTotal);
      sectionScores = flooredScores;
      if (floored) {
        const totalScore = cfg.compositeFromSections([sectionScores["Math"], sectionScores["Reading & Writing"]]);
        irtResult = {
          ...irtResult,
          sectionScores,
          totalScore,
          confidenceRange: {
            lower: Math.max(irtResult.confidenceRange.lower, Number(onboardingTotal)),
            upper: Math.max(irtResult.confidenceRange.upper, Number(onboardingTotal)),
          },
        };
      }
      return {
        bars,
        mathScore: String(sectionScores["Math"]),
        rwScore: String(sectionScores["Reading & Writing"]),
        examSummary: {
          mathCorrect: m.correct,
          mathTotal: m.total,
          rwCorrect: rw.correct,
          rwTotal: rw.total,
          totalCorrect,
          total: questions.length,
        },
        irtResult,
      };
    }

    let sectionScores = { ...irtResult.sectionScores };
    const { sectionScores: flooredActScores, floored: actFloored } = applyOnboardingScoreFloorToSections(sectionScores, cfg, onboardingTotal);
    sectionScores = flooredActScores;
    if (actFloored) {
      const totalScore = cfg.compositeFromSections(
        cfg.sections.filter((s) => s.inComposite).map((s) => sectionScores[s.label] ?? cfg.scale.compositeMin)
      );
      irtResult = {
        ...irtResult,
        sectionScores,
        totalScore,
        confidenceRange: {
          lower: Math.max(irtResult.confidenceRange.lower, Number(onboardingTotal)),
          upper: Math.max(irtResult.confidenceRange.upper, Number(onboardingTotal)),
        },
      };
    }

    const examSummary = { totalCorrect, total: questions.length, sections: {} };
    compositeSections.forEach((s) => {
      const st = secStats[s.label] || { correct: 0, total: 0 };
      examSummary.sections[s.label] = { correct: st.correct, total: st.total };
    });
    return { bars, sectionScores, examSummary, irtResult };
  }

  // Other tests: per-section scores on the test's own scale (e.g. AP).
  const midScore = Math.round((cfg.scale.sectionMin + cfg.scale.sectionMax) / 2);
  const sectionScores = {};
  const examSummary = { totalCorrect, total: questions.length, sections: {} };
  compositeSections.forEach((s) => {
    const st = secStats[s.label];
    sectionScores[s.label] = st.total ? cfg.sectionScoreFromAccuracy(st.correct / st.total) : midScore;
    examSummary.sections[s.label] = { correct: st.correct, total: st.total };
  });
  return { bars, sectionScores, examSummary };
};

const getLessonSection = (lesson) => {
  const domain = (lesson?.domain || "").trim();
  if (!domain) return "rw";
  if (MATH.includes(domain)) return "math";
  if (READING_WRITING.includes(domain)) return "rw";
  // Other tests (e.g. ACT): map the "math" section to the math layout, all
  // other sections (English/Reading/Science) to the verbal-styled layout.
  const sec = sectionForDomain(domain);
  if (sec) return sec.id === "math" ? "math" : "rw";
  const lower = domain.toLowerCase();
  if (
    lower.includes("algebra") ||
    lower.includes("geometry") ||
    lower.includes("trig") ||
    lower.includes("advanced math") ||
    lower.includes("problem solving") ||
    lower.includes("data analysis")
  ) return "math";
  return "rw";
};

