// URL routing (web only)
useEffect(() => {
  if (Platform.OS !== "web") return;
  const path = window.location.pathname;
  const query = new URLSearchParams(window.location.search);

  // Referral link (?ref=CODE) — pre-fill the visible invite-code field on
  // the register screen so the person can see it landed and still has to
  // submit the form with it present. Never auto-applied invisibly, and
  // never overwrites something the person already typed themselves.
  const refCode = query.get("ref");
  if (refCode && !manualReferralCode) setManualReferralCode(refCode.toUpperCase());

  // Class invite link (?class=CODE) — a teacher's "click to join" link.
  // A brand-new visitor gets the same treatment as ?ref= (pre-filled,
  // visible, still requires completing signup themselves). Someone who's
  // ALREADY signed in when they open the link is genuinely just one click
  // from joining, so this joins them directly rather than making them
  // re-type a code they just tapped — guarded to fire once per page load
  // (this effect re-runs on every screen change, e.g. once auth resolves
  // and screen flips to "app").
  const classCodeParam = query.get("class");
  if (classCodeParam && !classInviteHandledRef.current) {
    if (userId) {
      classInviteHandledRef.current = true;
      joinOrgClassByCode(classCodeParam);
    } else if (!joinClassCodeInput) {
      setJoinClassCodeInput(classCodeParam.toUpperCase());
    }
  }

  // Org-level invite link (?orgInvite=CODE) — educator/org-admin/program
  // manager/analyst, email-targeted (unlike ?class=, never joins silently
  // even for a logged-in visitor — orgInviteLanding always shows a confirm
  // step, since accepting attaches a NEW role to their account).
  const orgInviteParam = query.get("orgInvite");
  if (orgInviteParam && !orgInviteHandledRef.current) {
    orgInviteHandledRef.current = true;
    setOrgInviteCode(orgInviteParam);
    setPendingOrgInviteCode(orgInviteParam);
    loadOrgInvite(orgInviteParam);
    setScreen("orgInviteLanding");
  }

  // Optional return redirect after paying via a Stripe Payment Link
  // (?tutorCheckout=success|cancel) — only fires if a link's "after
  // payment" setting is configured to redirect here; nothing depends on
  // it. The purchase itself is recorded by stripe-webhook.js independently
  // of this redirect ever happening, so this is purely a confirmation +
  // refresh, not the source of truth for whether it succeeded.
  const tutorCheckoutParam = query.get("tutorCheckout");
  if (tutorCheckoutParam && !tutorCheckoutHandledRef.current && userId) {
    tutorCheckoutHandledRef.current = true;
    if (tutorCheckoutParam === "success") {
      showAlert("Payment received!", "We'll match you with a tutor shortly.");
      loadMyPendingPurchases();
    }
    setScreen("app");
    setView("studentTutoring");
  }

  if (!initialDeepLinkHandledRef.current && path === "/privacy") {
    initialDeepLinkHandledRef.current = true;
    legalReturnRef.current = { screen: "landing", view: null };
    setScreen("privacyPolicy");
    return;
  }
  if (!initialDeepLinkHandledRef.current && path === "/terms") {
    initialDeepLinkHandledRef.current = true;
    legalReturnRef.current = { screen: "landing", view: null };
    setScreen("termsOfService");
    return;
  }

  if (screen === "app") {
    // Don't remap view while still on a legal-page URL (goBackFromLegal updates URL first)
    if (path === "/privacy" || path === "/terms") return;

    if (path === "/quiz") setView("practice");
    else if (path === "/history") { loadScoreHistory(); setView("history"); }
    else if (path === "/growth") { loadScoreHistory(); setView("growth"); }
    else if (path === "/classes") setView("classes");
    else if (path === "/assignments") setView("assignments");
    else if (path === "/settings") setView("settings");
    else if (path === "/help") setView("help");
    else if (path === "/feedback") setView("feedback");
    else if (path === "/analytics") setView("timeAnalytics");
    else if (path === "/quiz/results") setView("results");
    else if (path === "/drills") setView("drills");
    else if (path === "/lessons") { loadLessons(); setView("lessons"); }
    else if (path === "/desmos-lessons") setView("desmosLessons");
    else if (path === "/games") setView("games");
    else if (path === "/diagnostic") { setDiagPath("choose"); setDiagStep(1); setView("diagnostic"); }
    else if (path === "/vocab") setView("vocab");
    else if (path === "/review") { loadScoreHistory(); setView("review"); }
    else if (path === "/testimonials") { loadTestimonials(); setView("testimonials"); }
    else if (path === "/cram-sheets") setView("cramsheets");
    else if (path === "/full-test") { setFullTestPhase("pickTest"); setView("fullTest"); }
    else if (path === "/smart-quiz") setView("smartQuiz");
    else if (path === "/study-plan") setView("studyPlan");
    else if (path === "/study-calendar") setView("studyCalendar");
    else if (path === "/promotions") { loadPromotions(); setView("promotions"); }
    else if (path === "/leaderboard") { loadLeaderboard(); setView("leaderboard"); }
    else if (path === "/tools") setView("tools");
    else if (path === "/extras") setView("extras");
    else if (path === "/weak-areas") setView("weakAreas");
    else setView("home");
  }
}, [screen]);

