                const cur = e.currentTarget.querySelector(".pj-cursor");
                if (!svg || !cur) return;
                const pts = [[60, 130], [160, 118], [260, 100], [360, 72], [460, 48]];
                const scores = ["1130", "1210", "1290", "1400", "1470"];
                const labels = ["Diagnostic", "Week 1", "Week 3", "Week 5", "Today"];
                const r = svg.getBoundingClientRect();
                const x = ((e.clientX - r.left) / r.width) * 520;
                const i = pts.reduce((b, p, j2) => (Math.abs(p[0] - x) < Math.abs(pts[b][0] - x) ? j2 : b), 0);
                cur.setAttribute("transform", `translate(${pts[i][0]},${pts[i][1]})`);
                cur.style.opacity = "1";
                cur.querySelector(".pj-score").textContent = scores[i];
                cur.querySelector(".pj-label").textContent = labels[i];
