              {GROWTH.map((v, i) => {
                const h = v * 1.6;
                const x = 34 + i * 48;
                const color = v >= 80 ? "#16a34a" : v >= 60 ? gold : "#dc2626";
                return <rect key={i} className="g-bar" data-i={i} x={x} y={180 - h} width="26" height={h} rx="4" fill={color} opacity="0.85" style={{ transitionDelay: `${i * 60}ms` }} />;
              })}
              <polyline className="g-line" points="47,106.4 95,96.8 143,101.6 191,87.2 239,79.2 287,84 335,71.2 383,63.2 431,55.2 479,45.6" fill="none" stroke={gold} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
